DEFAULT_SCENE  = "models/scenes/chemistry_lab_combined.xml"
DEFAULT_SPAWN  = [-1.0, 3.5, 0.22]
DEFAULT_POLICY = None
# Settle durations in seconds, converted to steps from the physics rate.
# Same real-time durations as the old 500 / 200 steps at 500 Hz.
WARMUP_SEC     = 1.0
RESETTLE_SEC   = 0.4
VIEWER_HZ      = 60
SHOW_CAMERA_INSETS = True
SHOW_HUD = True  # sim time, base velocity, pose and viewer fps, top left
# Camera renders with shadows/reflections. Turning this off is ~8x faster on
# software GL (VM without a GPU: ~90 ms vs ~700 ms per camera tick), but the
# images come out blown out white and the main viewer washes out too.
CAMERA_SHADOWS = True

CONTROL_GROUPS = [
    {
        "name": "base",
        "mode": "manual",
        "type": "drive",
        "actuators": ["left_motor", "right_motor"],
        "keys": DRIVE_CFG["keys"],
        "drive_params": DRIVE_CFG["drive_params"],
    },
]


# ===================================================================
# Performance / test settings
# ===================================================================

def _perf_settings():
    """Viewer / camera performance settings, overridable with CC_* env vars.

    Defaults are the fastest combination measured on the VirtualBox VM
    (about 130 ms/frame, was ~600-1000): viewer shadows/reflections off,
    one camera rendered per camera tick (take-turns, a VM performance
    setting; use CC_ROUNDROBIN=0 to record demos with every camera updating
    at CAMERA_HZ), vsync off paced to VIEWER_HZ.
    Resolution, shadow map size and window size made no measurable difference.

    CC_VIEW_SHADOWS=1  viewer shadows+reflections on   CC_ROUNDROBIN=0  render all cameras on every tick (demo recording)
    CC_CAM_SHADOWS=0   camera shadows off (washes out wrist cams)
    CC_VSYNC=1         vsync on (frames stall ~1 s if the window is hidden)
    CC_CAM_RES=WxH  CC_CAM_HZ=N  CC_SHADOWSIZE=N  CC_WIN=WxH  CC_HUD=0  CC_INSETS=0
    CC_FAKE_TELEOP=1   scripted fake operator + solver (no webcam needed)
    CC_BENCH_KEYS=10-20:E,30:T  hold keys on those frames (testing)   CC_BENCH_SNAP_FRAME=n
    CC_FINISH=1        glFinish after each swap
    CC_BENCH_FRAMES=N  run N frames, print per-phase timings, then exit
    CC_BENCH_SNAP=dir  save main view + camera images at frame 15
    CC_BENCH_LOG=file.csv  write base pose, pedestal height and every arm joint / finger to a CSV every 75 physics
                       steps (10 Hz of sim time), for before/after comparisons of the control loop
    CC_FAKE_TELEOP_SIMCLOCK=1  the fake operator and solver run on sim time instead of wall time (reproducible)
    """
    e = os.environ.get
    def wh(v):
        return tuple(int(x) for x in v.lower().split("x")) if v else None
    return {
        "frames": int(e("CC_BENCH_FRAMES", "0")),
        "cam_res": wh(e("CC_CAM_RES")),
        "cam_hz": float(e("CC_CAM_HZ")) if e("CC_CAM_HZ") else None,
        "roundrobin": e("CC_ROUNDROBIN") != "0",
        "cam_shadows": None if e("CC_CAM_SHADOWS") is None
                       else e("CC_CAM_SHADOWS") == "1",
        "view_shadows": e("CC_VIEW_SHADOWS") == "1",
        "shadowsize": int(e("CC_SHADOWSIZE")) if e("CC_SHADOWSIZE") else None,
        "win": wh(e("CC_WIN")) or (1280, 960),
        "vsync": int(e("CC_VSYNC", "0")),
        "snap_dir": e("CC_BENCH_SNAP"),
        "finish": e("CC_FINISH") == "1",
        "fake_teleop": e("CC_FAKE_TELEOP") == "1",
        "fake_simclock": e("CC_FAKE_TELEOP_SIMCLOCK") == "1",
        "log": e("CC_BENCH_LOG"),
        "inject": e("CC_BENCH_KEYS", ""),
        "snap_frame": int(e("CC_BENCH_SNAP_FRAME", "15")),
        "hud": e("CC_HUD") != "0",
        "insets": e("CC_INSETS") != "0",
    }



def _resolve_groups(model, groups):
    """Actuator ids per group ("remaining" = everything not claimed by the groups before and after it), as before."""
    claimed, resolved = set(), []
    for g in groups:
        spec = g["actuators"]
        if spec == "remaining":
            resolved.append(None)
        else:
            ids = []
            for name in spec:
                a = mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_ACTUATOR, name)
                if a < 0:
                    raise RuntimeError(f"Actuator '{name}' not in model.")
                ids.append(a)
            claimed.update(ids)
            resolved.append(ids)
    for i, g in enumerate(groups):
        if resolved[i] is None:
            resolved[i] = sorted(set(range(model.nu)) - claimed)
            claimed.update(resolved[i])
    for g, ids in zip(groups, resolved):
        print(f"  {g['name']:18s}  {g['mode']:8s}  act_ids={ids}  ({', '.join(model.actuator(a).name for a in ids)})")
    return resolved


def run(scene: str, spawn_pos, groups: list[dict], policy,
        mode: str = "manual", camera: int = 0, preview: bool = True,
        snapshot_every: float = 0.0, snapshot_dir: str | None = None,
        record: bool = False):
    """
    Main entry point (unchanged signature): load the scene, build the viewer and the sources, run the loop.

    Args:
        scene:      Path to MuJoCo scene XML (relative to PROJECT_ROOT).
        spawn_pos:  [x, y, z] or None to use the XML default.
        groups:     List of control-group dicts (see CONTROL_GROUPS): a manual "drive" group gives the base keys, "auto"
                    groups are driven by `policy`.
        policy:     Callable(observation, t) -> target angles array, or None.
                    When None, auto groups hold their actuators and only the
                    keyboard responds — i.e. pure keyboard control.
        mode:       "manual" (keyboard) or "teleop" (F2 switches the arms to the webcam operator).
    """
    bench = _perf_settings()
    global CAMERA_SHADOWS, SHOW_HUD, SHOW_CAMERA_INSETS
    SHOW_HUD = SHOW_HUD and bench["hud"]
    SHOW_CAMERA_INSETS = SHOW_CAMERA_INSETS and bench["insets"]
    if bench["cam_res"]:
        for cs in robot_specs.CAMERA_SPECS:
            cs["resolution"] = bench["cam_res"]
    if bench["cam_hz"]:
        robot_specs.CAMERA_HZ = bench["cam_hz"]
    if bench["cam_shadows"] is not None:
        CAMERA_SHADOWS = bench["cam_shadows"]

    # --- Load scene ---
    sim   = RobotSimulator(model_path=str(PROJECT_ROOT / scene),
                           cameras=robot_specs.CAMERA_SPECS,
                           pedestal_lift=robot_specs.PEDESTAL_SPECS)
    model = sim.model
    data  = sim.data

    # --- Groups: the drive group gives the base keys; auto groups belong to the policy ---
    resolved = _resolve_groups(model, groups)
    drive_cfg, auto_ids, claimed_ids = None, [], set()
    for g, ids in zip(groups, resolved):
        claimed_ids.update(ids)
        if g["mode"] == "manual" and g.get("type") == "drive":
            drive_cfg = {"keys": g["keys"], "drive_params": g.get("drive_params", {})}
        elif g["mode"] == "auto":
            auto_ids += ids
        elif g["mode"] == "manual" and g.get("type") == "joint":
            raise NotImplementedError("manual 'joint' control groups (per-joint step keys) were never used by CONTROL_GROUPS "
                                      "and are not carried into the refactored loop; the jog keys cover the arms")

    # --- Rates the launcher needs: the loop runs one command / viewer tick per `steps_per_frame` physics steps ---
    physics_hz = 1.0 / model.opt.timestep
    steps_per_frame = max(1, round(physics_hz / VIEWER_HZ))

    # --- Viewer, keys (real keys plus the CC_BENCH_KEYS test injection) ---
    viewer = make_glfw_viewer(model, data, {
        "win": bench["win"], "vsync": bench["vsync"], "view_shadows": bench["view_shadows"], "shadowsize": bench["shadowsize"],
        "hud": SHOW_HUD, "insets": SHOW_CAMERA_INSETS, "record": record, "snapshot_every": snapshot_every,
        "snapshot_dir": snapshot_dir, "bench_snap_dir": bench["snap_dir"], "bench_snap_frame": bench["snap_frame"],
        "finish": bench["finish"], "roundrobin": bench["roundrobin"], "viewer_hz": VIEWER_HZ,
        "record_fps": physics_hz / steps_per_frame, "has_teleop": mode == "teleop"})
    tick = [0]                                    # the loop keeps this equal to the frame number
    injected = set()
    # Test hook: CC_BENCH_KEYS="10-20:E,30:T" holds those keys on those frames.
    for tok in bench["inject"].split(","):
        if ":" in tok:
            fr, kname = tok.split(":", 1)
            lo_f, _, hi_f = fr.partition("-")
            for f_ in range(int(lo_f), int(hi_f or lo_f) + 1):
                injected.add((f_, key_code(kname)))
    held = lambda code: viewer["key_down"](code) or (tick[0], code) in injected
    viewer["set_held"](held)

    # --- Sources ---
    ped_aid = mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_ACTUATOR, robot_specs.PEDESTAL_SPECS["actuator_name"])
    ped_step = robot_specs.PEDESTAL_SPECS["jog_speed"] * steps_per_frame * model.opt.timestep
    sources = {"keyboard": make_keyboard_source(model, held, drive_cfg, ped_step, tuple(model.actuator_ctrlrange[ped_aid]),
                                                data=data, neck_specs=robot_specs.NECK_SPECS, points_fn=framing_points)}
    routes = {}
    if mode == "teleop":
        sources["teleop"] = make_teleop_source(model, data, camera=camera, preview=preview,
                                               fake=bench["fake_teleop"], simclock=bench["fake_simclock"])
    auto = robot_specs.NECK_AUTO_SPECS["mode"]
    if auto != "off" and (mode == "teleop" or auto == "always"):
        # the neck follows the grippers (teleop) and looks ahead while driving; the keyboard still commands it and wins
        sources["neck_auto"] = make_neck_auto_source(model, data, sources.get("teleop"), sources["keyboard"])
        routes["neck"] = ("keyboard", "neck_auto")
    if policy is not None and auto_ids:
        sources["policy"] = make_policy_source(model, policy, auto_ids)
        routes.update(sources["policy"]["routes"])

    print(f"\nBase:  arrow keys = drive/turn   SPACE = stop")
    print(f"Arms:  left arm  + 1 2 3 4 5 6 7 8 / - Q W E R T Y U I")
    print(f"       right arm + A S D F G H J K / - Z X C V B N M ,")
    print(f"       (columns = joints 1-7 then gripper; upper key +, gripper + opens)")
    print(f"Pedestal (placeholder lift):  Page Up = raise   Page Down = lower")
    print(f"Camera neck:  pan/lift/elbow/wrist  + 9 0 - =  / - O P [ ]    F7 = frame the task points   F8 = default aim (look ahead)")
    print(f"F3=save camera images  F4=snapshot  F5=trajectory log  "
          f"F6=record video + joint CSV  Esc=quit")
    if mode == "teleop":
        print(f"F2=toggle arms MANUAL / TELEOP (webcam); base keys work in both")

    cfg = {
        "source_hz": physics_hz / steps_per_frame, "camera_roundrobin": bench["roundrobin"], "camera_shadows": CAMERA_SHADOWS,
        "spawn_pos": spawn_pos, "warmup_s": WARMUP_SEC, "resettle_s": RESETTLE_SEC, "routes": routes,
        "claimed_ids": sorted(claimed_ids), "held": held, "tick_ref": tick, "bench_frames": bench["frames"],
        "bench_log": bench["log"], "preview": preview and mode == "teleop",
        "hotkeys": {"toggle_route": glfw.KEY_F2 if mode == "teleop" else None, "toggle_log": glfw.KEY_F5, "quit": glfw.KEY_ESCAPE},
    }
    run_loop(model, data, sources, cfg, viewer=viewer, logger=TrajectoryLogger())


# ===================================================================
# CLI
# ===================================================================

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--scene", default=DEFAULT_SCENE)
    parser.add_argument("--spawn", type=float, nargs=3, default=DEFAULT_SPAWN,
                        metavar=("X", "Y", "Z"))
    parser.add_argument("--no-spawn", action="store_true")
    parser.add_argument("--mode", choices=["manual", "auto", "teleop"],
                        default="manual",
                        help="manual: keyboard (default); auto: future policy "
                             "(not implemented); teleop: arms start on the "
                             "keyboard, F2 switches them to the webcam operator")
    parser.add_argument("--camera", type=int, default=0,
                        help="webcam device index for teleop (0=built-in, "
                             "1+=USB)")
    parser.add_argument("--snapshot-every", type=float, default=0.0,
                        help="save sim + camera PNGs every N seconds "
                             "(also: press F4 in the sim window)")
    parser.add_argument("--snapshot-dir", default=None,
                        help="where snapshots go (default: ./snapshots)")
    parser.add_argument("--record", action="store_true",
                        help="start recording the viewer (MP4 + joint CSV) on the "
                             "first frame; F6 stops / restarts it")
    parser.add_argument("--no-preview", action="store_true",
                        help="teleop: don't show the live camera window")
    args = parser.parse_args()
    if args.mode == "auto":
        parser.error("--mode auto is a placeholder for a future policy and "
                     "is not implemented yet")

    run(
        scene=args.scene,
        spawn_pos=None if args.no_spawn else args.spawn,
        groups=CONTROL_GROUPS,
        policy=DEFAULT_POLICY,
        mode=args.mode,
        camera=args.camera,
        preview=not args.no_preview,
        snapshot_every=args.snapshot_every,
        snapshot_dir=args.snapshot_dir,
        record=args.record,
    )


if __name__ == "__main__":
    main()